mapper.select:
SELECT ro.*, u.unit_number, b.name AS building_name, c.name AS community_name, r.name AS resident_name FROM repair_orders ro LEFT JOIN units u ON ro.unit_id = u.id LEFT JOIN buildings b ON u.building_id = b.id LEFT JOIN communities c ON b.community_id = c.id LEFT JOIN residents r ON ro.resident_id = r.id
AND ro.status = #{status} AND ro.category = #{category}
ORDER BY ro.id DESC

SELECT ro.*, u.unit_number FROM repair_orders ro
LEFT JOIN units u ON ro.unit_id = u.id
ORDER BY ro.id DESC LIMIT #{limit}
